from taf.ul.sc.generic_functionality import GenericFunctionality
from taf.ul.sc.util.decorators import GoToState
import re


class Egate(GenericFunctionality):
    """Class with keywords for EPCSim EGATE."""

    def __init__(self, device_name='EPCSIM', device=None, autoconnect=False, disable_statusbar=False, get_device=False):
        """
        :param device_name: Moler device name.
        :param device: Moler device. Initial state should be set to WS
        :param autoconnect: Connect to device after create object.
        :param disable_statusbar: Disable statusbar after connect to egate.
        """
        super(Egate, self).__init__(device_name=device_name, device=device,
                                    autoconnect=autoconnect, get_device=get_device)
        if disable_statusbar:
            self.connect_to_egate()
            self.disable_statusbar()

        self._port = None

    def connect_to_egate(self):
        """
        Connect to egate.

        :return: None
        """
        self.connect()
        self.device.goto_state("EPCSIM")

    def disable_statusbar(self):
        """
        Disable statusbar on egate.

        :return:
        """
        cmd = self.device.get_cmd(cmd_name='statusbar', cmd_params={'value': False})
        return cmd()

    def enable_statusbar(self):
        """
        Enable statusbar on egate.

        :return:
        """
        cmd = self.device.get_cmd(cmd_name='statusbar', cmd_params={'value': True})
        return cmd()

    @property
    def port(self):
        if not self._port:
            self._port = self._get_egate_port_from_device_configuration()

        return self._port

    def _get_egate_port_from_device_configuration(self):
        try:
            egate_params = self.device.get_configurations(source_state='UNIX_LOCAL', dest_state='EPCSIM')
        except KeyError:
            egate_params = self.device.get_configurations(source_state='PROXY_PC', dest_state='EPCSIM')

        return egate_params['command_params']['port']

    @GoToState.epcsim()
    def configure(self, config_file, timeout=240):
        """
        Configure EPCSim.

        :param config_file: Relative path to configuration file. Example: "config/sim-FZP-FDD2-211-gNBsim.cfg"
        :param timeout: timeout for sim_cfg command
        :return: Cfg command result (EPCSim state).
        """
        options = 'file={}'.format(config_file)
        cmd = self.device.get_cmd(cmd_name="sim_cfg", cmd_params={'options': options})
        result = cmd(timeout=timeout)
        return result

    @GoToState.epcsim()
    def start(self, timeout=60):
        """
        Start EPCSim.

        :return: Start command result (EPCSim state).
        """
        cmd = self.device.get_cmd(cmd_name="start")
        result = cmd(timeout=timeout)
        return result

    @GoToState.epcsim()
    def stop(self):
        """
        Stop EPCSim.

        :return: Stop command result (EPCSim state).
        """
        cmd = self.device.get_cmd(cmd_name="stop")
        result = cmd(timeout=20)
        return result

    @GoToState.epcsim()
    def reset(self):
        """
        Reset EPCSim.

        :return: Reset command result (EPCSim state).
        """
        cmd = self.device.get_cmd(cmd_name="reset")
        result = cmd(timeout=120)
        return result

    @GoToState.epcsim()
    def get_state(self):
        """
        Get EPCSim state.

        :return: State command result (EPCSim and device's states).
        """
        cmd = self.device.get_cmd(cmd_name="state")
        result = cmd()
        return result

    @GoToState.epcsim()
    def start_fake_paging(self, enbs, options=None):
        """
        Start S1:Paging generation towards eNB(s).

        :param enbs: eNB ids.
        :param options: (Optional) Additional options for mme_fake_paging_stop command.
                        Example: 'burst_size=1 burst_period=2 imsi=000:000:000000000 imsi_num=1 imsi_pct=1'
        :return: None.
        """
        cmd = self.device.get_cmd(cmd_name="mme_fake_paging_start", cmd_params={'enbs': enbs, 'options': options})
        cmd()

    @GoToState.epcsim()
    def stop_fake_paging(self, enbs, session_id=1, options=None):
        """
        Stop generation of fake S1:Pagings messages by MME to eNBs.

        :param enbs: eNB ids.
        :param session_id: Id of s1ap:paging request.
        :param options: (Optional) Additional options for mme_fake_paging_stop command.
                        Example: 'mme=1'
        :return: None.
        """
        cmd = self.device.get_cmd(cmd_name="mme_fake_paging_stop", cmd_params={'enbs': enbs,
                                                                               'session_id': session_id,
                                                                               'options': options})
        cmd()

    @GoToState.epcsim()
    def configure_rfm_filter(self, options=None):
        """
        Configure RFM filers which controls and displays RFM messages.

        :param options: set of params to enable/disable messages.
                        Example: 'disable=WARN uec=1,2'
        :return: None
        """

        cmd = self.device.get_cmd(cmd_name="sim_rfm_filter", cmd_params={'options': options})
        cmd()

    @GoToState.epcsim()
    def _sgw_stats(self, sgw_id='all', clear=False):
        """
        SGW stats.

        :param sgw_id: SGW IDs separated by comma.
        :param clear: clear options.
                        Example: 'clear=True' sgw_id='1,2' sgw='all'
        :return: SGW stats
        """
        stats = {}
        if sgw_id == 'all':
            sgw_state = self.get_sgw_state()
            sgw_id_list = [items['ID'] for key, items in sgw_state.items()]
        else:
            sgw_id_list = sgw_id.split(",")

        for sgw in sgw_id_list:
            run_sgw_stats = self.device.get_cmd(cmd_name="sgw_stats",
                                                cmd_params={"cmd_id": sgw, "clear": clear})
            stats[sgw] = run_sgw_stats()
        return stats

    def get_sgw_stats(self, sgw_id='all'):
        """
        Display SGW stats.

        :param sgw_id: SGW IDs separated by comma.
                        Example: sgw_id='1,2' sgw='all'
        :return: SGW stats
        """

        stats = self._sgw_stats(sgw_id=sgw_id)
        return stats

    def clear_sgw_stats(self, sgw_id='all'):
        """
        Clear SGW stats.

        :param sgw_id: SGW IDs separated by comma.
                        Example: sgw_id='1,2' sgw='all'
        :return: None
        """

        self._sgw_stats(sgw_id=sgw_id, clear=True)

    @GoToState.epcsim()
    def _pgw_stats(self, pgw_id='all', clear=False):
        """
        PGW stats.

        :param pgw_id:  PGW IDs separated by comma.
        :param clear: clear options.
                        Example: 'pgw_id='1,2' pgw_id='all' clear=True'
        :return: PGW stats
        """
        stats = {}
        if pgw_id == 'all':
            pgw_state = self.get_pgw_state()
            pgw_id_list = [items['ID'] for key, items in pgw_state.items()]
        else:
            pgw_id_list = pgw_id.split(",")

        options = None
        if clear is True:
            options = 'clear'

        for pgw in pgw_id_list:
            run_pgw_stats = self.device.get_cmd(cmd_name="pgw_stats",
                                                cmd_params={"pgw_id": pgw, "options": options})
            stats[pgw] = run_pgw_stats()

        return stats

    def get_pgw_stats(self, pgw_id='all'):
        """
        Display PGW stats.

        :param pgw_id: PGW IDs separated by comma.
                        Example: 'pgw_id='1,2' pgw_id='all'
        :return: PGW stats
        """

        stats = self._pgw_stats(pgw_id=pgw_id)
        return stats

    def clear_pgw_stats(self, pgw_id='all'):
        """
        Clear PGW stats.

        :param pgw_id: PGW IDs separated by comma.
                        Example: 'pgw_id='1,2' pgw_id='all'
        :return: None
        """

        self._pgw_stats(pgw_id=pgw_id, clear=True)

    def get_sgw_state(self):
        """
        Get SGW state.

        :return: Dictionary with state of all SGW.
        """
        state = self.get_state()
        sgw_state = {device['Device']: device for device in state['LIST'] if 'SGW' in device['Device']}
        for key, device in sgw_state.items():
            sgw_state[key]["ID"] = re.search(r"\d*$", key).group(0)
        return sgw_state

    def get_pgw_state(self):
        """
        Get PGW state.

        :return: Dictionary with state of all PGW.
        """
        state = self.get_state()
        pgw_state = {device['Device']: device for device in state['LIST'] if 'PGW' in device['Device']}
        for key, device in pgw_state.items():
            pgw_state[key]["ID"] = re.search(r"\d*$", key).group(0)
        return pgw_state

    @GoToState.epcsim()
    def get_version(self):
        """
        Get EGATE version.

        :return: EGATE version.
        """
        cmd = self.device.get_cmd(cmd_name="info_sim")
        result = cmd()
        return result['EPCSIM version']
